import styled from '@emotion/styled';

export const CustomSkeletonLoaderContainer = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: '8px',
  margin: '24px',
});

interface CustomSkeletonLoaderWrapperProps {
  $marginBottom?: boolean;
}

export const CustomSkeletonLoaderWrapper =
  styled.div<CustomSkeletonLoaderWrapperProps>(({ $marginBottom }) => ({
    display: 'flex',
    gap: '8px',
    marginBottom: $marginBottom ? '10px' : '0',
  }));
